import{z as o,x as A,o as e,c as d,q as n,j as r,D as E,d as t,s as l,S as s,b as B}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"Back 连续时间内幕交易","description":"","frontmatter":{"title":"Back 连续时间内幕交易","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/back-continuous-insider.md","filePath":"quant/back-continuous-insider.md","lastUpdated":1791413859000}'),p={name:"quant/back-continuous-insider.md"};function c(m,a,u,C,h,_){const i=A("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="back-连续时间内幕交易" tabindex="-1">Back 连续时间内幕交易 <a class="header-anchor" href="#back-连续时间内幕交易" aria-label="Permalink to &quot;Back 连续时间内幕交易&quot;">​</a></h1><div class="epigraph"><p>把知情交易写成对布朗滤波的控制问题：做市商的价格是累计订单流的函数，知情者在这条函数上选择自己的交易路径。连续时间里「线性深度」可以是均衡，也可以被非线性定价取代。</p><footer>—— Back, Insider Trading in Continuous Time, Review of Financial Studies, 1992</footer></div><p><a href="/quant/kyle-multiperiod">上一课</a>从 Kyle（1985）的多期拍卖走到连续极限，但仍借用正态线性结构：策略线性、价格对流量线性。缺口是：连续时间滤波要在怎样的概率空间上写严，知情者的控制问题如何陈述，以及<strong>不</strong>假设正态时均衡价格函数还是不是线性。Back（1992）把内幕交易收成连续时间的控制与滤波，而不是再切一刀单期 \\(\\lambda\\)。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Kyle 连续拍卖的启发是清楚的，技术上却留下缝：离散拍的极限、布朗噪声、知情者的容许策略类，需要一次说清。若价值不必正态，做市商的条件期望对累计流还是不是线性？若不是，知情者面对的就不是常系数冲击，最优路径也不是常系数 \\(\\beta\\)。问题变成：在连续时间、以累计订单流为状态的市场上，理性定价函数 \\(P(t,Y_t)\\) 与知情者的最优控制如何同时成立。</p><p>另一个缺口是信息到达的时间。Kyle 的 \\(V\\) 在 \\(t=0\\) 就固定。Back 的框架允许讨论定价函数的偏微分方程结构，为后来随机价值、随机噪声强度留下接口。本课只写 1992 年那一层：连续时间内幕、公开的是流、价格是流的函数。</p><h3 id="控制对象是路径-不是一拍的数量" tabindex="-1">控制对象是路径，不是一拍的数量 <a class="header-anchor" href="#控制对象是路径-不是一拍的数量" aria-label="Permalink to &quot;控制对象是路径，不是一拍的数量&quot;">​</a></h3><p>知情者选择的是有限变差或绝对连续的交易路径 \\(X\\)，累计公开流 \\(Y=X+Z\\)，\\(Z\\) 是布朗型噪声。做市商在每一瞬间只看见 \\(Y\\)，设定 \\(P_t=E[V\\mid \\mathcal{F}^Y_t]\\)。知情者预见到整个映射 \\(Y\\mapsto P\\)，最大化 \\(E\\int (V-P)\\,dX\\) 一类的利润。这与单期「选一个 \\(x\\)」不同：任何一段加速都会立刻改写 \\(Y\\) 的路径，从而改写整条价格路径。</p><p><span class="marginnote">术语翻译：「滤波」是用看得见的数据去猜看不见的东西——做市商只看得见混了噪声的总流 \\(Y\\)，要用它一路修正对真实价值 \\(V\\) 的猜测，像隔着毛玻璃看人影、随动作更新判断。「布朗噪声」则是没有任何规律可借的随机抖动，是知情者用来藏身的雾。</span></p><p><span class="marginnote">不要把 Back 读成「又一个 Kyle lambda」。线性均衡在正态设定下可以回收 Kyle 连续拍卖；一般分布下定价函数可以对 \\(Y\\) 非线性，深度沿路径变化。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准设定：区间 \\([0,1]\\)，期末公开 \\(V\\)。噪声 \\(Z\\) 为布朗运动（或带给定强度）。做市商竞争到半鞅价格，且 \\(P_t=E[V\\mid \\mathcal{F}^Y_t]\\)。猜一个定价函数 \\(P(t,y)\\)，知情者把 \\(P\\) 当给定解随机控制；把最优 \\(X\\) 送回滤波，要求一致性：在这条 \\(X\\) 下，\\(P(t,Y_t)\\) 的确是 \\(V\\) 的条件期望。</p><p>正态线性时，一致性给出与 Kyle 连续拍卖同族的特征：价格对 \\(Y\\) 线性，知情交易把定价误差按确定速度消耗。价值分布更一般时，Back 证明仍可存在均衡，但 \\(P\\) 对 \\(y\\) 的导数——即时深度的倒数——随 \\((t,y)\\) 变。直观是：累计流已经极端时，再来一单位流带来的信念更新不同，冲击不应是常数。</p><p><span class="marginnote">数字实例：正态线性均衡里冲击系数大致是 \\(\\lambda=\\sqrt{\\Sigma_0}/\\sigma_u\\)（\\(\\Sigma_0\\) 是价值先验方差，\\(\\sigma_u\\) 是噪声流强度）。噪声流翻倍，深度翻倍，每单位订单流的推价减半；先验不确定性越大，市场越浅。两个旋钮一起解释了为什么财报前夜流更贵、冷门股的滑点更大。</span></p><h3 id="滤波与执行的同一条状态" tabindex="-1">滤波与执行的同一条状态 <a class="header-anchor" href="#滤波与执行的同一条状态" aria-label="Permalink to &quot;滤波与执行的同一条状态&quot;">​</a></h3><p>状态压缩在公开流 \\(Y\\) 上。知情者比做市商多知道 \\(V\\)，因此他知道价格「错在哪」，也知道自己的 \\(dX\\) 会怎样推动 \\(Y\\)。最优控制的一阶条件把「再交易一单位的直接利润」与「把 \\(Y\\) 推走导致的价格重估」抵平——与多期离散的跨期权衡同构，只是改写在生成元上。</p>',16)),(e(),r(s,null,{default:E(()=>[l(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E7%9F%A5%E6%83%85%E8%80%85%E6%8C%81%E6%9C%89%20V%22%5D%20--%3E%20Ctrl%5B%22%E9%80%89%E6%8B%A9%E8%B7%AF%E5%BE%84%20X%22%5D%0A%20%20Z%5B%22%E5%B8%83%E6%9C%97%E5%99%AA%E5%A3%B0%20Z%22%5D%20--%3E%20Y%5B%22%E5%85%AC%E5%BC%80%E6%B5%81%20Y%20%3D%20X%20%2B%20Z%22%5D%0A%20%20Ctrl%20--%3E%20Y%0A%20%20Y%20--%3E%20P%5B%22P(t%2CY)%20%3D%20E%5BV%20%7C%20%E6%B5%81%E7%9A%84%E5%8E%86%E5%8F%B2%5D%22%5D%0A%20%20P%20--%3E%20Obj%5B%22%E5%88%A9%E6%B6%A6%E7%A7%AF%E5%88%86%20(V-P)%20dX%22%5D%0A%20%20Obj%20-.-%3E%7C%22%E6%9C%80%E4%BC%98%E6%8E%A7%E5%88%B6%22%7C%20Ctrl%0A%20%20Ctrl%20-.-%3E%7C%22%E6%BB%A4%E6%B3%A2%E4%B8%80%E8%87%B4%E6%80%A7%22%7C%20P%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[t("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"连续时间把「藏在噪声里」写成绝对连续路径对布朗的绝对连续扰动：知情流不能对布朗奇异，否则滤波立刻分离出内幕。这比口头说「要拆单」更硬：容许策略类本身禁止瞬时砸盘。价格作为 \\(Y\\) 的函数，保证做市商没有相对公开流的免费午餐；知情者的租金来自对 \\(V\\) 的初值优势，随揭示消耗。",-1)),(e(),r(s,null,{default:E(()=>[l(i,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22%E7%9F%A5%E6%83%85%E8%B7%AF%E5%BE%84%E9%80%89%E5%93%AA%E7%A7%8D%3F%22%7D%0A%20%20Q%20--%3E%7C%E5%A5%87%E5%BC%82%3A%20%E7%9E%AC%E6%97%B6%E7%A0%B8%E7%9B%98%7C%20SING%5B%22dX%20%E5%AF%B9%E5%B8%83%E6%9C%97%E5%A5%87%E5%BC%82%3A%20%E9%9B%BE%E7%9B%96%E4%B8%8D%E4%BD%8F%22%5D%0A%20%20SING%20--%3E%20SEP%5B%22%E6%BB%A4%E6%B3%A2%E7%9E%AC%E9%97%B4%E5%88%86%E7%A6%BB%E5%87%BA%E5%86%85%E5%B9%95%22%5D%0A%20%20SEP%20--%3E%20FAIL%5B%22%E4%BB%B7%E6%A0%BC%E4%B8%80%E6%AD%A5%E8%B7%B3%E5%88%B0%E7%9C%9F%E5%AE%9E%E4%BB%B7%E5%80%BC%3A%20%E7%A7%9F%E9%87%91%E6%B8%85%E9%9B%B6%22%5D%0A%20%20Q%20--%3E%7C%E7%BB%9D%E5%AF%B9%E8%BF%9E%E7%BB%AD%3A%20%E9%A1%BA%E5%99%AA%E5%A3%B0%E6%8B%86%E5%8D%95%7C%20ACC%5B%22dX%20%E4%B8%8E%E5%99%AA%E5%A3%B0%E5%90%8C%E9%98%B6%3A%20%E8%97%8F%E5%9C%A8%E6%B5%81%E9%87%8C%22%5D%0A%20%20ACC%20--%3E%20GRAD%5B%22%E4%BF%A1%E6%81%AF%E9%9A%8F%E6%97%B6%E9%97%B4%E6%B8%90%E6%AC%A1%E6%B3%84%E5%85%A5%E4%BB%B7%E6%A0%BC%22%5D%0A%20%20GRAD%20--%3E%20RENT%5B%22%E5%88%9D%E5%80%BC%E4%BC%98%E5%8A%BF%E6%85%A2%E6%85%A2%E6%B6%88%E8%80%97%20%E5%AE%8C%E6%88%90%E4%BA%8E%E6%9C%9F%E6%9C%AB%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">直觉类比：可以把它想象成混在人流里转移——步速与人群一致（绝对连续）就无人注意，突然冲刺（奇异）立刻暴露。知情利润因此自带速度上限：不是不能动，是只能按人群的节奏挪；跑得越急，隐身时间越短，单价也越差。</span></p><p>与<a href="/quant/lob-structure">限价簿</a>对照：Back 没有双向深度、没有撤单，价格是出清映射而不是 BBO。它解释的是<strong>流作为信号</strong>在连续时间如何被写入价格，不是排队几何。要把 \\(P(t,y)\\) 翻译成买卖价差，需要另加报价结构。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>单一知情者、外生布朗噪声、期末一次性公开，仍是边界。价值若自己是扩散（后续 Back–Pedersen 等），内幕变成关于漂移的知识，最优路径会跟踪随机基本面，而不是消耗一个常数 \\(V\\)。多个知情者引入抢跑式揭示。电子限价簿上做市发生在挂单里，冲击依赖簿形，见后文 Parlour / Foucault，不在这条滤波里。</p><p>经验上没有「Back 系数」可直接 OLS。能对照的是：冲击是否随累计不平衡非线性变化、是否随临近公开时点变陡。那仍是描述，不是把 1992 年的 \\(P(t,y)\\) 估出来。</p><p><span class="marginnote">Kyle（1985）连续拍卖与 Back（1992）是同一纲领的两个精度：前者给出正态线性的经济图像，后者给出一般连续时间的控制陈述。阅读顺序不要跳过前者的机制直接套 PDE。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Back 把内幕交易写成对公开订单流的连续时间控制，价格是流的滤波。</li><li>正态时可回收 Kyle 连续拍卖的线性深度；一般分布下即时冲击随 \\((t,y)\\) 变。</li><li>容许策略对布朗绝对连续，禁止自我揭示的奇异砸盘。</li><li>对象仍是出清价，不是买卖价差或 LOB 队列。</li><li>出处：Back, <em>Review of Financial Studies</em>, 1992；先修连续拍卖见 Kyle, <em>Econometrica</em>, 1985。</li></ul>',8))])}const D=o(p,[["render",c]]);export{P as __pageData,D as default};
